// Extrae slug del comercio, entorno y adjunto de planilla desde el correo IMAP.
// Acepta precios-<slug>@, precios.<slug>@ y precios+<slug>@ (el slug puede llevar guiones: precios-panaderia-central).
// Staging solo con prefijo explícito: precios-dev-<slug>@margenx.tech o precios-<slug>@dev.margenx.tech. El resto va a producción.
const SLUG_RE = /precios[-.+](dev[-.+])?([a-z0-9]+(?:-[a-z0-9]+)*)@(dev\.)?margenx\.tech/i;
const EXT_RE = /\.(xlsx|xls|csv)$/i;
const OWN = String($env.IMAP_USER || '').toLowerCase();

function addrText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (v.text) return v.text;
  if (Array.isArray(v.value)) return v.value.map((a) => a.address).join(',');
  return JSON.stringify(v);
}
function firstAddress(v) {
  if (v && Array.isArray(v.value) && v.value[0]) return String(v.value[0].address || '').toLowerCase();
  const m = addrText(v).match(/[^\s<>,;"']+@[^\s<>,;"']+/);
  return m ? m[0].toLowerCase() : '';
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const headers = j.headers || {};
  const from = firstAddress(j.from);

  // Evita bucles: ignora correos propios, rebotes y respuestas automáticas.
  const autoSubmitted = String(headers['auto-submitted'] || '').toLowerCase();
  if (
    (OWN && from === OWN) ||
    /^(mailer-daemon|postmaster|no-?reply)/.test(from) ||
    (autoSubmitted && autoSubmitted !== 'no')
  ) {
    continue;
  }

  const recipients = [
    addrText(j.to),
    addrText(j.cc),
    String(headers['x-original-to'] || ''),
    String(headers['delivered-to'] || '')
  ].join(' ');

  const match = recipients.match(SLUG_RE);
  const devTag = match ? match[1] : '';
  const rawSlug = match ? match[2] : '';
  const devDomain = match ? match[3] : '';

  const slugLower = rawSlug ? rawSlug.toLowerCase() : '';
  const isDev = Boolean(devTag || devDomain);

  const binary = item.binary || {};
  const binaryKey = Object.keys(binary).find((k) => EXT_RE.test(String(binary[k].fileName || '')));
  const fileName = binaryKey ? String(binary[binaryKey].fileName) : '';
  const ext = fileName ? fileName.match(EXT_RE)[1].toLowerCase() : '';

  let error = '';
  if (!slugLower) {
    error = 'El destinatario no incluye el identificador del comercio. Enviá la lista a precios-<comercio>@margenx.tech (por ejemplo precios-panaderia-central@margenx.tech).';
  } else if (!binaryKey) {
    error = 'El correo no tiene un adjunto .xlsx, .xls o .csv con la lista de precios.';
  }

  out.push({
    json: {
      mailId: String(out.length),
      slug: slugLower,
      isDev,
      from,
      subject: String(j.subject || ''),
      fileName,
      ext,
      binaryKey: binaryKey || '',
      error
    },
    binary,
  });
}
return out;

// Convierte un adjunto CSV a filas, detectando coma / punto y coma / tabulación.
// Cada fila queda ligada (pairedItem) al correo del que salió; un CSV solo con encabezado emite un ítem vacío (marcador).
const out = [];
for (let idx = 0; idx < $input.all().length; idx++) {
  const key = $input.all()[idx].json.binaryKey;
  const buf = await this.helpers.getBinaryDataBuffer(idx, key);
  let text = buf.toString('utf8');
  if (text.includes('\uFFFD')) text = buf.toString('latin1');
  text = text.replace(/^﻿/, '');

  const firstLine = text.split(/\r?\n/).find((l) => l.trim() !== '') || '';
  const count = (ch) => (firstLine.match(new RegExp(ch === '\t' ? '\t' : '\\' + ch, 'g')) || []).length;
  const delimiter = [';', ',', '\t'].sort((a, b) => count(b) - count(a))[0];

  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; }
      else if (c === '"') quoted = false;
      else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === delimiter) { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some((v) => v.trim() !== '')) rows.push(row);
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some((v) => v.trim() !== '')) rows.push(row);

  const header = (rows.shift() || []).map((h) => h.trim());
  for (const r of rows) {
    const obj = {};
    header.forEach((h, i) => { if (h) obj[h] = (r[i] ?? '').trim(); });
    out.push({ json: obj, pairedItem: { item: idx } });
  }
  if (rows.length === 0) out.push({ json: {}, pairedItem: { item: idx } }); // CSV sin filas: marcador para avisar al remitente
}
return out;

// Normaliza columnas (código / descripción / precio) y arma lotes para la API, un resultado por correo.
// Las filas se asignan a su correo de origen (pairedItem), así varios correos en una misma ejecución no se mezclan.
// Un correo sin filas (CSV solo con encabezado / hoja vacía) llega como ítem vacío y termina en error al remitente.
const BATCH = 5000; // máximo por request del webhook
const mails = $('Extraer Slug y Adjunto').all().map((i) => i.json).filter((m) => !m.error);

function mailOf(i) {
  try {
    const m = $('Extraer Slug y Adjunto').itemMatching(i);
    if (m && m.json && m.json.mailId !== undefined) return m.json;
  } catch (e) { /* sin pairedItem */ }
  return mails.length === 1 ? mails[0] : null;
}

const norm = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const ALIASES = {
  code: ['codigo', 'cod', 'art', 'articulo', 'sku', 'ref', 'referencia', 'cod art', 'cod articulo', 'codigo articulo', 'item'],
  description: ['descripcion', 'detalle', 'producto', 'nombre', 'denominacion'],
  price: ['precio final', 'final', 'precio', 'costo', 'precio lista', 'precio unitario', 'importe', 'p lista'],
};

function parsePrice(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (!s) return NaN;
  const lastDot = s.lastIndexOf('.');
  const lastComma = s.lastIndexOf(',');
  if (lastDot >= 0 && lastComma >= 0) {
    s = lastComma > lastDot ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (lastComma >= 0) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (/^-?\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  }
  return Number(s);
}
function parseCode(v) {
  return String(v ?? '').trim();
}

function processMail(meta, rows) {
  const fail = (error) => [{ json: { ...meta, ok: false, error } }];
  if (rows.length === 0) return fail('La planilla no tiene filas con código y precio válidos.');

  const keys = [...new Set(rows.flatMap((r) => Object.keys(r)))];
  const findKey = (list) => {
    for (const a of list) {
      const k = keys.find((key) => norm(key) === a);
      if (k) return k;
    }
    for (const a of list) {
      const k = keys.find((key) => norm(key).split(' ').includes(a));
      if (k) return k;
    }
    return null;
  };
  const cols = { code: findKey(ALIASES.code), description: findKey(ALIASES.description), price: findKey(ALIASES.price) };
  if (!cols.code || !cols.price) {
    return fail('No encontramos las columnas de código y precio en la planilla (se esperan encabezados como "Código" y "Precio").');
  }

  const items = [];
  let invalid = 0;
  for (const r of rows) {
    const code = parseCode(r[cols.code]);
    const price = parsePrice(r[cols.price]);
    if (!code || !(price > 0)) { invalid++; continue; }
    const item = { code, price: Math.round(price * 100) / 100 };
    if (cols.description && r[cols.description] !== undefined && String(r[cols.description]).trim() !== '') {
      item.description = String(r[cols.description]).trim();
    }
    items.push(item);
  }
  if (items.length === 0) return fail('La planilla no tiene filas con código y precio válidos.');

  const batches = Math.ceil(items.length / BATCH);
  const out = [];
  for (let b = 0; b < batches; b++) {
    out.push({
      json: {
        ok: true,
        mailId: meta.mailId,
        accountSlug: meta.slug,
        isDev: Boolean(meta.isDev),
        from: meta.from,
        fileName: meta.fileName,
        items: items.slice(b * BATCH, (b + 1) * BATCH),
        rowsRead: rows.length,
        rowsInvalid: invalid,
        batchIndex: b + 1,
        batches,
      },
    });
  }
  return out;
}

// Este nodo recibe una pasada por rama (CSV y XLSX): solo se responde por los correos que traen filas en esta pasada.
const groups = new Map();
$input.all().forEach((it, i) => {
  const m = mailOf(i);
  if (!m) return;
  if (!groups.has(m.mailId)) groups.set(m.mailId, { meta: m, rows: [] });
  // un ítem vacío ({}) es el marcador de "archivo sin filas": cuenta como correo presente, no como fila
  if (Object.keys(it.json || {}).length > 0) groups.get(m.mailId).rows.push(it.json);
});

const result = [];
for (const { meta, rows } of groups.values()) result.push(...processMail(meta, rows));
return result;

// POST /api/webhooks/supplier-prices con política de reintentos:
//  - 2xx            -> éxito
//  - 4xx            -> falla de inmediato (reintentar no lo arregla: slug inexistente, planilla inválida, secreto incorrecto, lista demasiado grande)
//  - 5xx / timeout / error de red -> hasta 3 reintentos con espera creciente (2 s, 5 s, 10 s)
const WAITS = [2000, 5000, 10000];
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const meta = {
    mailId: j.mailId, accountSlug: j.accountSlug, from: j.from, fileName: j.fileName,
    rowsRead: j.rowsRead, rowsInvalid: j.rowsInvalid, batchIndex: j.batchIndex, batches: j.batches,
    isDev: Boolean(j.isDev), // el resumen arma los enlaces con el entorno de la lista
  };

  // URL base por entorno, con o sin /api. Un correo de staging sin MARGENX_DEV_API_URL no se despacha: nunca cae en producción.
  const rawUrl = j.isDev ? $env.MARGENX_DEV_API_URL : ($env.MARGENX_API_URL || 'https://api.margenx.tech');
  if (!rawUrl) {
    out.push({ json: { ...meta, dispatchOk: false, status: 0, attempts: 0, apiError: 'MARGENX_DEV_API_URL no está configurada.' } });
    continue;
  }
  const baseUrl = String(rawUrl).replace(/\/+$/, '').replace(/\/api$/, '');
  const url = baseUrl + '/api/webhooks/supplier-prices';

  let attempt = 0;
  let last;
  while (true) {
    attempt++;
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url,
        headers: { 'x-margenx-webhook-secret': $env.INTERNAL_WEBHOOK_SECRET, 'Content-Type': 'application/json' },
        body: { accountSlug: j.accountSlug, items: j.items },
        json: true,
        timeout: 60000,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });
      const status = Number(res.statusCode);
      if (status >= 200 && status < 300) { 
        last = { ok: true, status, body: res.body }; 
        break; 
      }
      // Guardamos el body incluso en error para poder leer el 413
      last = { 
        ok: false, 
        status, 
        body: res.body,
        message: typeof res.body === 'string' ? res.body.slice(0, 300) : JSON.stringify(res.body || {}).slice(0, 300) 
      };
      if (status < 500) break; // 4xx: no se reintenta
    } catch (e) {
      last = { ok: false, status: 0, message: String((e && e.message) || e).slice(0, 300) }; // red / timeout
    }
    if (attempt > WAITS.length) break;
    await sleep(WAITS[attempt - 1]);
  }

  // Extraemos el error específico si viene en el body (ej. 413 PAYLOAD_TOO_LARGE)
  let apiError = last.ok ? undefined : last.message;
  if (!last.ok && last.body && last.body.error) {
    apiError = last.body.error;
  }

  out.push({ 
    json: { 
      ...meta, 
      dispatchOk: last.ok, 
      status: last.status, 
      attempts: attempt, 
      body: last.body, 
      apiError 
    } 
  });
}
return out;

// Consolida las respuestas de la API (uno o más lotes) y arma el resumen para el dueño del comercio.
// Orden del mail: primero lo que pide una decisión (cuarentena, códigos sin mapear, margen crítico) con su enlace; después el resumen.
// <plantilla-mail-margenx>
// Plantilla compartida de los mails de MargenX (resumen de ingesta y alertas de margen).
// Fuente única: infra/n8n/plantillas/mail-margenx.js. No editar este bloque en n8n:
// se copia a los workflows con `node infra/n8n/plantillas/sincronizar.mjs`.
const MX_APP = { prod: 'https://margenx.tech', dev: 'https://dev.margenx.tech' };
const MX_TONOS = {
  peligro: { fondo: '#fef2f2', borde: '#ef4444', titulo: '#991b1b', texto: '#7f1d1d', chipFondo: '#450a0a', chipTexto: '#fca5a5', chipBorde: '#7f1d1d' },
  aviso: { fondo: '#fffbeb', borde: '#f59e0b', titulo: '#92400e', texto: '#78350f', chipFondo: '#451a03', chipTexto: '#fcd34d', chipBorde: '#78350f' },
  info: { fondo: '#eef2ff', borde: '#4f46e5', titulo: '#3730a3', texto: '#312e81', chipFondo: '#1e1b4b', chipTexto: '#c7d2fe', chipBorde: '#3730a3' },
  ok: { fondo: '#f0fdf4', borde: '#22c55e', titulo: '#166534', texto: '#14532d', chipFondo: '#052e16', chipTexto: '#86efac', chipBorde: '#14532d' },
};
function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
// Número con separador de miles argentino: 2.500
function mxEntero(n) {
  return (Number(n) || 0).toLocaleString('es-AR');
}
// "1 fila" / "2 filas": el singular solo para exactamente 1
function mxCantidad(n, singular, plural) {
  return `${mxEntero(n)} ${Number(n) === 1 ? singular : plural}`;
}
function mxPorcentaje(n) {
  return (Number(n) || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
}
function mxPesos(n) {
  return new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n) || 0);
}
function mxBoton(href, etiqueta) {
  return `<a href="${escapeHtml(href)}" target="_blank" style="background-color: #4f46e5; color: #ffffff; padding: 10px 18px; font-size: 14px; font-weight: 700; text-decoration: none; border-radius: 6px; display: inline-block;">${escapeHtml(etiqueta)}</a>`;
}
// Bloque destacado con título, contenido (HTML ya escapado) y un botón opcional
function mxAviso(tono, titulo, contenidoHtml, boton) {
  const t = MX_TONOS[tono] || MX_TONOS.info;
  const accion = boton ? `<p style="margin: 12px 0 0 0;">${mxBoton(boton.href, boton.etiqueta)}</p>` : '';
  return `<div style="background-color: ${t.fondo}; border-left: 4px solid ${t.borde}; padding: 12px 12px; border-radius: 0 8px 8px 0; margin: 0 0 16px 0;">
  <p style="margin: 0; font-size: 15px; font-weight: 700; color: ${t.titulo};">${escapeHtml(titulo)}</p>
  <div style="margin: 6px 0 0 0; font-size: 14px; line-height: 1.5; color: ${t.texto};">${contenidoHtml}</div>${accion}
</div>`;
}
// Tabla de productos bajo su margen mínimo, con el botón "Ajustar" de cada uno
function mxTablaProductos(filas) {
  const cuerpo = filas.map((f) => `<tr style="border-bottom: 1px solid #e2e8f0;">
  <td style="padding: 10px 8px; font-size: 14px; font-weight: 600; color: #0f172a;">${escapeHtml(f.nombre)}<div style="font-size: 12px; font-weight: 400; color: #64748b;">Nuevo costo: ${escapeHtml(mxPesos(f.costo))}</div></td>
  <td style="padding: 10px 8px; font-size: 13px; text-align: right; white-space: nowrap;"><span style="background-color: #fee2e2; color: #b91c1c; font-weight: 700; padding: 3px 6px; border-radius: 4px; border: 1px solid #fecaca; display: inline-block;">${escapeHtml(mxPorcentaje(f.margen))}</span><div style="font-size: 12px; color: #475569; margin-top: 4px;">mín. ${escapeHtml(mxPorcentaje(f.minimo))}</div></td>
  <td style="padding: 10px 8px; text-align: right;"><a href="${escapeHtml(f.enlace)}" target="_blank" style="background-color: #4f46e5; color: #ffffff; padding: 6px 10px; font-size: 12px; font-weight: 600; text-decoration: none; border-radius: 4px; display: inline-block;">Ajustar</a></td>
</tr>`).join('');
  return `<table width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse: collapse; border: 1px solid #e2e8f0; width: 100%; background-color: #ffffff;">
<thead><tr style="background-color: #f1f5f9; text-align: left;">
  <th style="padding: 8px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase;">Producto</th>
  <th style="padding: 8px; font-size: 11px; font-weight: 700; color: #b91c1c; text-transform: uppercase; text-align: right;">Margen</th>
  <th style="padding: 8px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase; text-align: right;"></th>
</tr></thead>
<tbody>${cuerpo}</tbody>
</table>`;
}
// Documento completo: encabezado de marca, etiqueta de estado, contenido y pie
function mxDocumento({ titulo, etiqueta, tono, contenidoHtml, pieHtml }) {
  const t = MX_TONOS[tono] || MX_TONOS.info;
  return `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(titulo)}</title>
</head>
<body style="margin: 0; padding: 0; background-color: #f8fafc; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #0f172a;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f8fafc; padding: 16px 8px;">
    <tr>
      <td align="center">
        <table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; background-color: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0;">
          <tr>
            <td style="background-color: #0f172a; padding: 18px 16px;">
              <table width="100%" cellpadding="0" cellspacing="0" border="0">
                <tr>
                  <td>
                    <span style="font-size: 20px; font-weight: 800; color: #ffffff; letter-spacing: 0.5px;">MARGEN<span style="color: #6366f1;">X</span></span>
                    <span style="font-size: 11px; color: #94a3b8; display: block; margin-top: 2px; text-transform: uppercase; letter-spacing: 1px;">Control de rentabilidad en tiempo real</span>
                  </td>
                  <td align="right">
                    <span style="background-color: ${t.chipFondo}; color: ${t.chipTexto}; font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 9999px; border: 1px solid ${t.chipBorde}; text-transform: uppercase; white-space: nowrap; display: inline-block;">${escapeHtml(etiqueta)}</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding: 20px 16px; font-size: 14px; line-height: 1.5; color: #334155;">
              ${contenidoHtml}
            </td>
          </tr>
          <tr>
            <td style="background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 16px; text-align: center;">
              ${pieHtml ? `<p style="margin: 0 0 8px 0; font-size: 12px; color: #64748b;">${pieHtml}</p>` : ''}
              <p style="margin: 0; font-size: 11px; color: #94a3b8;">MargenX &bull; Soporte: contacto@margenx.tech</p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}
// </plantilla-mail-margenx>

const MAX_CODES = 20;
// NOT_FOUND no es un error: el código todavía no está vinculado a una presentación ("sin mapear").
const OTHER_REASONS = {
  AMBIGUOUS: 'estar en más de un proveedor activo',
  INACTIVE_SUPPLIER: 'proveedor inactivo',
};
const listCodes = (codes) => {
  const shown = codes.slice(0, MAX_CODES).join(', ');
  const more = codes.length > MAX_CODES ? ` y ${mxEntero(codes.length - MAX_CODES)} más` : '';
  return `${shown}${more}.`;
};

// Un resumen por correo recibido: agrupa los lotes (respuestas de la API) de cada mailId.
const byMail = new Map();
for (const i of $input.all()) {
  const k = String(i.json.mailId ?? '');
  if (!byMail.has(k)) byMail.set(k, []);
  byMail.get(k).push(i.json);
}
const results = [];
for (const batchItems of byMail.values()) {
  const meta = batchItems[0];
  const responses = batchItems.map((i) => i.body || {});
  const account = responses.map((r) => r.account).find((a) => a && a.ownerEmail) || {};
  const ownerEmail = String(account.ownerEmail || '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(ownerEmail)) {
    // Sin email del dueño en la respuesta de la API no se envía nada (el resumen nunca va al remitente de la lista).
    continue;
  }
  const tradeName = String(account.tradeName || meta.accountSlug || '');
  const appBase = meta.isDev ? MX_APP.dev : MX_APP.prod;

  const sum = (k) => responses.reduce((a, r) => a + (Number(r[k]) || 0), 0);
  const received = sum('received');
  const updated = sum('updated');
  const unchanged = sum('unchanged');
  const quarantined = sum('quarantined');
  const duplicates = sum('duplicates');
  const discarded = sum('discarded');
  const rowsInvalid = Number(meta.rowsInvalid) || 0;

  // Detalle de códigos no aplicados (contrato #208: discardedCodes = [{code, reason}], la API lo acota a 100 por lote).
  const discardedCodes = responses.flatMap((r) => (Array.isArray(r.discardedCodes) ? r.discardedCodes : []));
  const unmapped = [];
  const others = new Map();
  for (const d of discardedCodes) {
    const code = String((d && d.code) ?? '');
    if (d && d.reason === 'NOT_FOUND') { unmapped.push(code); continue; }
    const label = OTHER_REASONS[d && d.reason] || 'otro motivo';
    if (!others.has(label)) others.set(label, []);
    others.get(label).push(code);
  }
  const critical = responses.flatMap((r) => (Array.isArray(r.criticalProductsAlerts) ? r.criticalProductsAlerts : []));
  const productLink = (p) => {
    const id = String(p.productId || '').replace(/[^a-zA-Z0-9_-]/g, '');
    return id ? `${appBase}/productos/${id}` : `${appBase}/productos`;
  };

  // 1. Decisiones pendientes, en este orden.
  const decisions = [];
  if (quarantined > 0) {
    const title = `${mxCantidad(quarantined, 'precio quedó', 'precios quedaron')} en cuarentena`;
    const body = quarantined === 1
      ? 'Cambió más de lo esperado y no se aplicó. Revisá el precio y decidí si lo liberás o lo rechazás.'
      : 'Cambiaron más de lo esperado y no se aplicaron. Revisá los precios y decidí si los liberás o los rechazás.';
    const href = `${appBase}/proveedores/cuarentena`;
    decisions.push({
      text: `${title}. ${body}\nBandeja de cuarentena: ${href}`,
      html: mxAviso('aviso', title, `<p style="margin: 0;">${escapeHtml(body)}</p>`, { href, etiqueta: 'Revisar la cuarentena' }),
    });
  }
  if (unmapped.length > 0) {
    const title = mxCantidad(unmapped.length, 'código sin mapear', 'códigos sin mapear');
    const body = `${unmapped.length === 1 ? 'No está vinculado' : 'No están vinculados'} a ninguna presentación de tus proveedores, así que no ${unmapped.length === 1 ? 'se actualizó' : 'se actualizaron'}. Para que la próxima lista ${unmapped.length === 1 ? 'lo actualice, cargá el código' : 'los actualice, cargá los códigos'} en la presentación del proveedor.`;
    const href = `${appBase}/proveedores`;
    decisions.push({
      text: `${title}. ${body}\nCódigos: ${listCodes(unmapped)}\nProveedores: ${href}`,
      html: mxAviso('info', title, `<p style="margin: 0;">${escapeHtml(body)}</p><p style="margin: 6px 0 0 0;">Códigos: ${escapeHtml(listCodes(unmapped))}</p>`, { href, etiqueta: 'Ir a Proveedores' }),
    });
  }
  if (critical.length > 0) {
    const title = `${mxCantidad(critical.length, 'producto quedó', 'productos quedaron')} debajo de su margen mínimo`;
    const rows = critical.map((p) => ({ nombre: p.productName || 'Producto', costo: p.newCost, margen: p.currentMarginPercent, minimo: p.minMarginPercent, enlace: productLink(p) }));
    decisions.push({
      text: `${title}:\n${rows.map((f) => `- ${f.nombre}: margen ${mxPorcentaje(f.margen)} (mínimo ${mxPorcentaje(f.minimo)}), nuevo costo ${mxPesos(f.costo)}. Ajustar: ${f.enlace}`).join('\n')}`,
      html: mxAviso('peligro', title, `<p style="margin: 0 0 10px 0;">Revisá su precio de venta o su receta.</p>${mxTablaProductos(rows)}`),
    });
  }

  // 2. Resumen de la lista.
  const stats = [
    `Leímos ${mxCantidad(received, 'fila', 'filas')} de la lista.`,
    `${mxCantidad(updated, 'precio actualizado', 'precios actualizados')}.`,
    ...(unchanged > 0 ? [`${mxCantidad(unchanged, 'precio', 'precios')} sin cambios.`] : []),
    ...(duplicates > 0 ? [`${mxCantidad(duplicates, 'fila repetida', 'filas repetidas')} en la lista (vale la última).`] : []),
    ...(rowsInvalid > 0 ? [`${mxCantidad(rowsInvalid, 'fila ignorada', 'filas ignoradas')} por no tener código o precio válido.`] : []),
    ...[...others.entries()].map(([label, codes]) => `No se aplicaron por ${label} (${mxEntero(codes.length)}): ${listCodes(codes)}`),
  ];
  if (discardedCodes.length === 0 && discarded > 0) {
    stats.push(`${mxCantidad(discarded, 'fila no se aplicó', 'filas no se aplicaron')}.`);
  } else if (discardedCodes.length > 0 && discardedCodes.length < discarded) {
    stats.push(`Se detallan ${mxEntero(discardedCodes.length)} de ${mxEntero(discarded)} filas no aplicadas.`);
  }

  const intro = `Procesamos la lista de precios${meta.fileName ? ` ${meta.fileName}` : ''} para ${tradeName}.`;
  const introHtml = `<p style="margin: 0 0 16px 0;">Hola! Procesamos la lista de precios${meta.fileName ? ` <em>${escapeHtml(meta.fileName)}</em>` : ''} para <strong>${escapeHtml(tradeName)}</strong>.</p>`;
  const allGood = 'No hay nada para revisar: no quedaron precios en cuarentena ni códigos por vincular, y ningún producto cayó debajo de su margen mínimo.';

  const text = [
    'Hola!',
    intro,
    ...(decisions.length ? ['PARA REVISAR', ...decisions.map((d) => d.text)] : [allGood]),
    ['RESUMEN', ...stats].join('\n'),
    'Equipo MargenX',
  ].join('\n\n');

  const contenidoHtml = [
    introHtml,
    decisions.length
      ? `<h2 style="margin: 0 0 12px 0; font-size: 16px; color: #0f172a;">Para revisar</h2>${decisions.map((d) => d.html).join('')}`
      : mxAviso('ok', 'Todo en orden', `<p style="margin: 0;">${escapeHtml(allGood)}</p>`),
    `<h2 style="margin: 8px 0 8px 0; font-size: 16px; color: #0f172a;">Resumen</h2><ul style="margin: 0; padding-left: 20px;">${stats.map((l) => `<li style="margin: 0 0 4px 0;">${escapeHtml(l)}</li>`).join('')}</ul>`,
  ].join('');

  const subjectParts = [
    ...(quarantined > 0 ? [mxCantidad(quarantined, 'precio en cuarentena', 'precios en cuarentena')] : []),
    ...(unmapped.length > 0 ? [mxCantidad(unmapped.length, 'código sin mapear', 'códigos sin mapear')] : []),
    ...(critical.length > 0 ? [mxCantidad(critical.length, 'producto en margen crítico', 'productos en margen crítico')] : []),
  ];
  const subject = `[MargenX] Resumen de tu lista de precios${subjectParts.length ? ` — ${subjectParts.join(', ')}` : ''}`;
  const html = mxDocumento({
    titulo: 'Resumen de tu lista de precios',
    etiqueta: decisions.length ? 'Para revisar' : 'Todo en orden',
    tono: critical.length ? 'peligro' : decisions.length ? 'aviso' : 'ok',
    contenidoHtml,
    pieHtml: `Comercio: <strong>${escapeHtml(tradeName)}</strong>`,
  });

  results.push({ json: { ownerEmail, subject, text, html } });
}
return results;

// Arma el correo de error para el remitente (adjunto/slug inválido, planilla ilegible o API caída).
// Cada ítem trae su propio remitente y archivo (from / fileName), así que se responde a quien corresponde aunque haya varios correos.
function escapeHtml(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
const REASONS = {
  404: 'El comercio indicado en la dirección no existe o está inactivo en MargenX.',
  400: 'La planilla tiene un formato que MargenX no pudo procesar.',
  401: 'Hubo un problema interno de autenticación. Ya avisamos al equipo técnico.',
  403: 'Hubo un problema interno de autenticación. Ya avisamos al equipo técnico.',
  413: 'La lista es demasiado grande para procesarla de una vez (más de 5 MB). Dividila en dos o más archivos y envialos por separado a esta misma dirección.',
};
const UNAVAILABLE = 'No pudimos comunicarnos con MargenX después de 3 intentos. Reenviá la lista en unos minutos.';
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const j = item.json || {};
  let reason;

  if (j.dispatchOk === false) {
    // El detalle de la API (apiError) no se reenvía al proveedor: solo el motivo según el status.
    reason = REASONS[j.status] || (j.status >= 400 && j.status < 500 ? 'MargenX rechazó la planilla recibida.' : UNAVAILABLE);
  } else {
    reason = typeof j.error === 'string' && j.error ? j.error : UNAVAILABLE;
  }

  if (!j.from) continue;
  const key = `${j.mailId}|${reason}`;
  if (seen.has(key)) continue; // varios lotes del mismo correo fallando por lo mismo: un solo aviso
  seen.add(key);
  const file = j.fileName ? ` (${j.fileName})` : '';
  out.push({
    json: {
      to: j.from,
      subject: '[MargenX] No pudimos procesar tu lista de precios',
      text: `Hola!\n\nRecibimos tu correo${file} pero no pudimos procesar la lista de precios.\n\nMotivo: ${reason}\n\nCuando lo corrijas, volvé a enviarla a la misma dirección.\n\nEquipo MargenX`,
      html: `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#1f2937"><h2 style="color:#b91c1c;font-size:18px">No pudimos procesar tu lista de precios</h2><p>Recibimos tu correo${escapeHtml(file)} pero la importación no se pudo completar.</p><p style="background:#fef2f2;border-left:4px solid #b91c1c;padding:12px"><strong>Motivo:</strong> ${escapeHtml(reason)}</p><p>Cuando lo corrijas, volvé a enviarla a la misma dirección.</p><p style="color:#6b7280;font-size:12px">Equipo MargenX</p></div>`,
    },
  });
}
return out;
